import 'package:flutter/material.dart';
import '../../data/database_helper.dart';
import '../../widgets/common_widgets.dart';

class ProductsScreen extends StatefulWidget { const ProductsScreen({super.key}); @override State<ProductsScreen> createState()=>_ProductsScreenState(); }
class _ProductsScreenState extends State<ProductsScreen> with SingleTickerProviderStateMixin {
 final db=DatabaseHelper.instance, search=TextEditingController();
 final fields={for(final f in ['code','name','english_name','unit','cost_price','sale_price','notes'])f:TextEditingController()};
 late final TabController tabs;
 List<Map<String,Object?>> products=[],categories=[],warehouses=[],units=[],barcodes=[],reorder=[],batches=[],stock=[];
 int? id,categoryId; String filter='',saleMethod='قطعة'; bool tracking=true,weighted=false,active=true,negative=false,busy=false;
 @override void initState(){super.initState();tabs=TabController(length:5,vsync:this);reload();}
 @override void dispose(){tabs.dispose();search.dispose();for(final c in fields.values)c.dispose();super.dispose();}
 void msg(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 Future<void> reload()async{try{final r=await Future.wait([db.query('products',orderBy:'name COLLATE NOCASE'),db.query('categories',orderBy:'name'),db.query('warehouses',orderBy:'name')]);if(!mounted)return;setState((){products=r[0];categories=r[1];warehouses=r[2];});if(id!=null)await loadChildren();}catch(e){msg('تعذر التحميل: $e');}}
 Future<void> loadChildren()async{if(id==null)return;final r=await Future.wait([db.query('product_units',where:'product_id=?',whereArgs:[id]),db.query('barcodes',where:'product_id=?',whereArgs:[id]),db.query('reorder_levels',where:'product_id=?',whereArgs:[id]),db.query('product_batches',where:'product_id=?',whereArgs:[id],orderBy:'expiry_date'),db.query('inventory',where:'product_id=?',whereArgs:[id])]);if(!mounted)return;setState((){units=r[0];barcodes=r[1];reorder=r[2];batches=r[3];stock=r[4];});}
 void clearForm(){setState((){id=null;categoryId=null;saleMethod='قطعة';tracking=true;weighted=false;active=true;negative=false;for(final c in fields.values)c.clear();fields['unit']!.text='قطعة';fields['cost_price']!.text='0';fields['sale_price']!.text='0';units=[];barcodes=[];reorder=[];batches=[];stock=[];});tabs.animateTo(0);}
 void select(Map<String,Object?> p){setState((){id=(p['id'] as num).toInt();for(final k in fields.keys){fields[k]!.text=(p[k]??'').toString();}categoryId=(p['category_id'] as num?)?.toInt();saleMethod=(p['sale_method']??'قطعة').toString();tracking=((p['stock_tracking'] as num?)?.toInt()??1)==1;negative=((p['negative_stock'] as num?)?.toInt()??0)==1;active=((p['is_active'] as num?)?.toInt()??1)==1;weighted=saleMethod=='وزن';});loadChildren();}
 Future<void> save()async{if(fields['name']!.text.trim().isEmpty){msg('اسم الصنف مطلوب');return;}final c=double.tryParse(fields['cost_price']!.text),p=double.tryParse(fields['sale_price']!.text);if(c==null||p==null||c<0||p<0){msg('الأسعار يجب أن تكون أرقامًا غير سالبة');return;}setState(()=>busy=true);try{final d=<String,Object?>{'code':fields['code']!.text.trim().isEmpty?null:fields['code']!.text.trim(),'name':fields['name']!.text.trim(),'english_name':fields['english_name']!.text.trim(),'category_id':categoryId,'unit':fields['unit']!.text.trim().isEmpty?'قطعة':fields['unit']!.text.trim(),'sale_method':weighted?'وزن':saleMethod,'cost_price':c,'sale_price':p,'notes':fields['notes']!.text.trim(),'stock_tracking':tracking?1:0,'negative_stock':negative?1:0,'is_active':active?1:0};if(id==null){id=await db.insert('products',d);msg('تم إنشاء الصنف');}else{await db.update('products',d,where:'id=?',whereArgs:[id]);msg('تم تحديث الصنف');}await reload();await loadChildren();}catch(e){msg('تعذر الحفظ: $e');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> remove()async{if(id==null)return;try{await db.delete('products',where:'id=?',whereArgs:[id]);clearForm();await reload();}catch(e){msg('لا يمكن حذف صنف مرتبط بحركات: $e');}}
 Future<void> addChild(String table,String title,List<String> names)async{if(id==null){msg('احفظ الصنف أولاً');return;}final cs={for(final f in names)f:TextEditingController()};final result=await showDialog<Map<String,Object?>?>(context:context,builder:(ctx)=>AlertDialog(title:Text('إضافة '+title),content:SizedBox(width:380,child:Column(mainAxisSize:MainAxisSize.min,children:names.map((f)=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:cs[f],decoration:InputDecoration(labelText:switch(f){'unit_name'=>'اسم الوحدة','factor'=>'معامل التحويل','sale_price'=>'سعر البيع','barcode'=>'الباركود','minimum'=>'حد النقص','maximum'=>'الحد الأعلى','batch_no'=>'رقم الدفعة','expiry_date'=>'تاريخ الصلاحية','qty'=>'الكمية','warehouse_id'=>'معرف المخزن',_=>f}))).toList())),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:(){final d=<String,Object?>{};for(final f in names){final v=cs[f]!.text.trim();if(v.isEmpty)continue;if(['factor','sale_price','minimum','maximum','qty','warehouse_id'].contains(f)){final n=double.tryParse(v);if(n==null){ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('أدخل قيمة رقمية')));return;}d[f]=n;}else{d[f]=v;}}Navigator.pop(ctx,d);},child:const Text('حفظ'))]));for(final c in cs.values)c.dispose();if(result==null)return;try{await db.insert(table,{...result,'product_id':id});await loadChildren();}catch(e){msg('تعذر إضافة '+title+': $e');}}
 Widget table(String title,String tableName,List<Map<String,Object?>> rows,List<String> keys,List<String> labels,{bool readonly=false,List<String> inputFields=const[]})=>SectionCard(title:title+' ('+rows.length.toString()+')',trailing:readonly?null:ActionButton('إضافة',icon:Icons.add,onPressed:()=>addChild(tableName,title,inputFields)),child:rows.isEmpty?const Padding(padding:EdgeInsets.all(16),child:Text('لا توجد بيانات')):SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:labels.map((x)=>DataColumn(label:Text(x))).toList(),rows:rows.map((r)=>DataRow(cells:keys.map((k)=>DataCell(Text((r[k]??'—').toString()))).toList())).toList()));
 @override Widget build(BuildContext context){final list=products.where((p)=>filter.isEmpty||p.values.any((v)=>v.toString().toLowerCase().contains(filter.toLowerCase()))).toList();return Padding(padding:const EdgeInsets.all(14),child:Column(children:[Wrap(spacing:8,children:[ActionButton('جديد',icon:Icons.add,onPressed:clearForm),ActionButton('حفظ',icon:Icons.save,primary:true,onPressed:busy?()=>{}:save),ActionButton('تحديث',icon:Icons.refresh,onPressed:reload),ActionButton('تفريغ',icon:Icons.cleaning_services,onPressed:clearForm),ActionButton('حذف',icon:Icons.delete_outline,onPressed:remove),ActionButton('إغلاق',icon:Icons.close,onPressed:()=>Navigator.maybePop(context))]),const SizedBox(height:10),Expanded(child:Row(children:[SizedBox(width:280,child:Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(children:[TextField(controller:search,decoration:const InputDecoration(labelText:'بحث عام',prefixIcon:Icon(Icons.search)),onChanged:(v)=>setState(()=>filter=v.trim())),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>setState(()=>filter=search.text.trim()),icon:const Icon(Icons.search),label:const Text('بحث'))),IconButton(onPressed:reload,icon:const Icon(Icons.refresh))]),const Divider(),Expanded(child:ListView(children:list.map((p)=>ListTile(selected:(p['id'] as num).toInt()==id,title:Text((p['name']??'').toString()),subtitle:Text('الكود: '+(p['code']??'—').toString()),onTap:()=>select(p))).toList()))]))),const SizedBox(width:10),Expanded(child:Card(child:Column(children:[TabBar(controller:tabs,isScrollable:true,tabs:const[Tab(text:'الأساسية'),Tab(text:'الوحدات والأسعار'),Tab(text:'الباركود'),Tab(text:'إعادة الطلب'),Tab(text:'الدفعات والأرصدة')]),Expanded(child:TabBarView(controller:tabs,children:[
 ListView(padding:const EdgeInsets.all(14),children:[Wrap(spacing:10,runSpacing:10,children:[for(final e in fields.entries)SizedBox(width:220,child:TextField(controller:e.value,decoration:InputDecoration(labelText:switch(e.key){'code'=>'التكويد','name'=>'اسم الصنف *','english_name'=>'الاسم الإنجليزي','unit'=>'الوحدة الأساسية','cost_price'=>'سعر التكلفة','sale_price'=>'سعر البيع','notes'=>'ملاحظات',_=>e.key},maxLines:e.key=='notes'?2:1))),SizedBox(width:220,child:DropdownButtonFormField<int>(value:categoryId,decoration:const InputDecoration(labelText:'التصنيف'),items:categories.map((c)=>DropdownMenuItem(value:(c['id'] as num).toInt(),child:Text((c['name']??'').toString()))).toList(),onChanged:(v)=>setState(()=>categoryId=v))),SizedBox(width:220,child:DropdownButtonFormField<String>(value:saleMethod,decoration:const InputDecoration(labelText:'طريقة البيع'),items:const['قطعة','وزن','طول','حجم'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>saleMethod=v??'قطعة')))]),Wrap(spacing:8,children:[FilterChip(label:const Text('تتبع مخزون'),selected:tracking,onSelected:(v)=>setState(()=>tracking=v)),FilterChip(label:const Text('صنف موزون'),selected:weighted,onSelected:(v)=>setState(()=>weighted=v)),FilterChip(label:const Text('مخزون سالب'),selected:negative,onSelected:(v)=>setState(()=>negative=v)),FilterChip(label:const Text('نشط'),selected:active,onSelected:(v)=>setState(()=>active=v))])]),
 ListView(padding:const EdgeInsets.all(8),children:[table('الوحدات ومعاملات التحويل','product_units',units,const['unit_name','factor','sale_price'],const['الوحدة','المعامل','السعر'],inputFields:const['unit_name','factor','sale_price']),table('الأرصدة حسب المخزن','inventory',stock,const['warehouse_id','qty'],const['المخزن','الرصيد'],readonly:true)]),
 ListView(padding:const EdgeInsets.all(8),children:[table('باركودات الصنف','barcodes',barcodes,const['barcode','unit_id'],const['الباركود','الوحدة'],inputFields:const['barcode','unit_id'])]),
 ListView(padding:const EdgeInsets.all(8),children:[table('حدود إعادة الطلب حسب المخزن','reorder_levels',reorder,const['warehouse_id','minimum','maximum'],const['المخزن','حد النقص','الحد الأعلى'],inputFields:const['warehouse_id','minimum','maximum'])]),
 ListView(padding:const EdgeInsets.all(8),children:[table('الدفعات والصلاحية','product_batches',batches,const['warehouse_id','batch_no','expiry_date','qty'],const['المخزن','رقم الدفعة','الصلاحية','الكمية'],inputFields:const['warehouse_id','batch_no','expiry_date','qty']),table('الرصيد الحالي','inventory',stock,const['warehouse_id','qty'],const['المخزن','الرصيد'],readonly:true)])
]))])))])));}
}
